"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { CHART_PALETTE as PALETTE } from "../lib/chart-utils";

/**
 * Grafieken — eigen SVG-implementatie, geen chartbibliotheek.
 * Kleuren komen uit --chart-1 … --chart-6 (afgeleid van het design).
 */

export interface ChartDatum {
  label: string;
  value: number;
  color?: string;
}

/* ============================ Sparkline ============================ */
export interface SparklineProps extends React.HTMLAttributes<HTMLDivElement> {
  data: number[];
  height?: number;
  color?: string;
  /** Vult het vlak onder de lijn. */
  filled?: boolean;
  strokeWidth?: number;
}

export const Sparkline = React.forwardRef<HTMLDivElement, SparklineProps>(function Sparkline(
  { data, height = 40, color = "var(--chart-1)", filled = true, strokeWidth = 2, className, ...rest },
  ref
) {
  const width = 100;
  const max = Math.max(...data, 1);
  const min = Math.min(...data, 0);
  const span = max - min || 1;
  const points = data.map((value, index) => {
    const x = (index / Math.max(data.length - 1, 1)) * width;
    const y = height - ((value - min) / span) * (height - strokeWidth) - strokeWidth / 2;
    return `${x},${y}`;
  });

  return (
    <div ref={ref} className={cn("lui-sparkline", className)} style={{ height }} {...rest}>
      <svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" width="100%" height={height}>
        {filled && (
          <polygon points={`0,${height} ${points.join(" ")} ${width},${height}`} fill={color} opacity="0.12" />
        )}
        <polyline
          points={points.join(" ")}
          fill="none"
          stroke={color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          vectorEffect="non-scaling-stroke"
        />
      </svg>
    </div>
  );
});

/* ============================ BarChart ============================ */
export interface BarChartProps extends React.HTMLAttributes<HTMLDivElement> {
  data: ChartDatum[];
  height?: number;
  /** Toont de waarde boven elke staaf. */
  showValues?: boolean;
  formatValue?: (value: number) => string;
  color?: string;
}

export const BarChart = React.forwardRef<HTMLDivElement, BarChartProps>(function BarChart(
  { data, height = 180, showValues, formatValue, color = "var(--chart-1)", className, ...rest },
  ref
) {
  const max = Math.max(...data.map((item) => item.value), 1);

  return (
    <div ref={ref} className={cn("lui-barchart", className)} style={{ height }} {...rest}>
      {data.map((item, index) => (
        <div className="lui-barchart-col" key={`${item.label}-${index}`}>
          {showValues && (
            <span className="lui-barchart-value">
              {formatValue ? formatValue(item.value) : item.value}
            </span>
          )}
          <div className="lui-barchart-track">
            <div
              className="lui-barchart-bar"
              style={{
                height: `${(item.value / max) * 100}%`,
                background: item.color ?? color,
                animationDelay: `${index * 45}ms`,
              }}
              title={`${item.label}: ${item.value}`}
            />
          </div>
          <span className="lui-barchart-label">{item.label}</span>
        </div>
      ))}
    </div>
  );
});

/* ============================ LineChart ============================ */
export interface LineSeries {
  name: string;
  data: number[];
  color?: string;
}

export interface LineChartProps extends React.HTMLAttributes<HTMLDivElement> {
  series: LineSeries[];
  labels?: string[];
  height?: number;
  /** Vult het vlak onder de lijn. */
  area?: boolean;
  /** Toont horizontale hulplijnen. */
  grid?: boolean;
  legend?: boolean;
}

export const LineChart = React.forwardRef<HTMLDivElement, LineChartProps>(function LineChart(
  { series, labels, height = 200, area, grid = true, legend = true, className, ...rest },
  ref
) {
  const width = 300;
  const padding = 6;
  const all = series.flatMap((entry) => entry.data);
  const max = Math.max(...all, 1);
  const min = Math.min(...all, 0);
  const span = max - min || 1;
  const count = Math.max(...series.map((entry) => entry.data.length), 2);

  const toPoints = (values: number[]) =>
    values.map((value, index) => {
      const x = (index / (count - 1)) * (width - padding * 2) + padding;
      const y = height - padding - ((value - min) / span) * (height - padding * 2);
      return { x, y };
    });

  return (
    <div ref={ref} className={cn("lui-linechart", className)} {...rest}>
      <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} preserveAspectRatio="none">
        {grid &&
          [0, 0.25, 0.5, 0.75, 1].map((fraction) => (
            <line
              key={fraction}
              x1={0}
              x2={width}
              y1={padding + fraction * (height - padding * 2)}
              y2={padding + fraction * (height - padding * 2)}
              className="lui-linechart-grid"
            />
          ))}
        {series.map((entry, index) => {
          const color = entry.color ?? PALETTE[index % PALETTE.length];
          const points = toPoints(entry.data);
          const path = points.map((point) => `${point.x},${point.y}`).join(" ");
          return (
            <g key={entry.name}>
              {area && (
                <polygon
                  points={`${padding},${height - padding} ${path} ${width - padding},${height - padding}`}
                  fill={color}
                  opacity="0.12"
                />
              )}
              <polyline
                points={path}
                fill="none"
                stroke={color}
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
                vectorEffect="non-scaling-stroke"
              />
            </g>
          );
        })}
      </svg>
      {labels && (
        <div className="lui-linechart-labels">
          {labels.map((label) => (
            <span key={label}>{label}</span>
          ))}
        </div>
      )}
      {legend && series.length > 0 && (
        <ChartLegend
          items={series.map((entry, index) => ({
            label: entry.name,
            color: entry.color ?? PALETTE[index % PALETTE.length],
          }))}
        />
      )}
    </div>
  );
});

/* ============================ DonutChart ============================ */
export interface DonutChartProps extends React.HTMLAttributes<HTMLDivElement> {
  data: ChartDatum[];
  size?: number;
  thickness?: number;
  centerLabel?: React.ReactNode;
  centerValue?: React.ReactNode;
  legend?: boolean;
}

export const DonutChart = React.forwardRef<HTMLDivElement, DonutChartProps>(function DonutChart(
  { data, size = 160, thickness = 22, centerLabel, centerValue, legend = true, className, ...rest },
  ref
) {
  const total = data.reduce((sum, item) => sum + item.value, 0) || 1;
  const radius = (size - thickness) / 2;
  const circumference = 2 * Math.PI * radius;
  let offset = 0;

  return (
    <div ref={ref} className={cn("lui-donut", className)} {...rest}>
      <div className="lui-donut-figure" style={{ width: size, height: size }}>
        <svg width={size} height={size}>
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            fill="none"
            strokeWidth={thickness}
            className="lui-donut-track"
          />
          {data.map((item, index) => {
            const fraction = item.value / total;
            const dash = fraction * circumference;
            const circle = (
              <circle
                key={`${item.label}-${index}`}
                cx={size / 2}
                cy={size / 2}
                r={radius}
                fill="none"
                stroke={item.color ?? PALETTE[index % PALETTE.length]}
                strokeWidth={thickness}
                strokeDasharray={`${dash} ${circumference - dash}`}
                strokeDashoffset={-offset}
                transform={`rotate(-90 ${size / 2} ${size / 2})`}
              >
                <title>{`${item.label}: ${item.value}`}</title>
              </circle>
            );
            offset += dash;
            return circle;
          })}
        </svg>
        {(centerValue || centerLabel) && (
          <div className="lui-donut-center">
            {centerValue && <span className="lui-donut-value">{centerValue}</span>}
            {centerLabel && <span className="lui-donut-label">{centerLabel}</span>}
          </div>
        )}
      </div>
      {legend && (
        <ChartLegend
          items={data.map((item, index) => ({
            label: item.label,
            color: item.color ?? PALETTE[index % PALETTE.length],
            value: item.value,
          }))}
          vertical
        />
      )}
    </div>
  );
});

/* ============================ Legend ============================ */
export interface ChartLegendProps extends React.HTMLAttributes<HTMLDivElement> {
  items: Array<{ label: string; color: string; value?: number | string }>;
  vertical?: boolean;
}

export const ChartLegend = React.forwardRef<HTMLDivElement, ChartLegendProps>(function ChartLegend(
  { items, vertical, className, ...rest },
  ref
) {
  return (
    <div ref={ref} className={cn("lui-legend", vertical && "lui-legend-vertical", className)} {...rest}>
      {items.map((item) => (
        <span className="lui-legend-item" key={item.label}>
          <span className="lui-legend-swatch" style={{ background: item.color }} />
          {item.label}
          {item.value !== undefined && <span className="lui-legend-value">{item.value}</span>}
        </span>
      ))}
    </div>
  );
});

/* ============================ Charts ============================ */
.lui-sparkline { width: 100%; display: block; }
.lui-sparkline svg { display: block; width: 100%; }

/* ---------- BarChart ---------- */
.lui-barchart { display: flex; align-items: flex-end; gap: 10px; width: 100%; }
.lui-barchart-col {
  flex: 1; min-width: 0; height: 100%;
  display: flex; flex-direction: column; align-items: center; gap: 7px;
}
.lui-barchart-value { font-size: 11.5px; font-weight: 650; color: var(--text-2); font-family: var(--mono); }
.lui-barchart-track { width: 100%; flex: 1; display: flex; align-items: flex-end; }
.lui-barchart-bar {
  width: 100%; min-height: 4px; border-radius: 6px 6px 3px 3px;
  transform-origin: bottom; animation: lui-bar-grow .5s var(--ease-out) both;
}
@keyframes lui-bar-grow { from { transform: scaleY(0); } to { transform: scaleY(1); } }
.lui-barchart-label {
  font-size: 11px; color: var(--text-3);
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* ---------- LineChart ---------- */
.lui-linechart { width: 100%; display: flex; flex-direction: column; gap: 8px; }
.lui-linechart svg { display: block; width: 100%; overflow: visible; }
.lui-linechart-grid { stroke: var(--border); stroke-width: 1; stroke-dasharray: 3 4; }
.lui-linechart-labels {
  display: flex; justify-content: space-between;
  font-size: 11px; color: var(--text-3);
}

/* ---------- DonutChart ---------- */
.lui-donut { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; }
.lui-donut-figure { position: relative; display: grid; place-items: center; flex: none; }
.lui-donut-figure svg { position: absolute; inset: 0; }
.lui-donut-track { stroke: var(--surface-3); }
.lui-donut-center { display: flex; flex-direction: column; align-items: center; gap: 1px; z-index: 1; }
.lui-donut-value { font-size: 22px; font-weight: 700; letter-spacing: -0.02em; color: var(--text); }
.lui-donut-label { font-size: 11.5px; color: var(--text-3); }

/* ---------- Legend ---------- */
.lui-legend { display: flex; flex-wrap: wrap; gap: 14px; }
.lui-legend-vertical { flex-direction: column; gap: 9px; }
.lui-legend-item { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--text-2); }
.lui-legend-swatch { width: 10px; height: 10px; border-radius: 3px; flex: none; }
.lui-legend-value { color: var(--text); font-weight: 650; margin-left: 4px; }

/* ==================== Gedeeld door de assen-grafieken ==================== */
/* Gebruikt door AreaChart, ComboChart, ScatterChart en RadarChart via lib/chart-utils. */
.lui-chart { position: relative; width: 100%; display: flex; flex-direction: column; gap: 10px; }
.lui-chart-plot { position: relative; width: 100%; }
.lui-chart-plot svg { display: block; width: 100%; overflow: visible; touch-action: pan-y; }

.lui-chart-grid { stroke: var(--border); stroke-width: 1; stroke-dasharray: 3 4; }
.lui-chart-axis { stroke: var(--border-strong); stroke-width: 1; }
.lui-chart-tick { fill: var(--text-3); font-size: 11px; font-family: inherit; }
.lui-chart-axis-title { fill: var(--text-3); font-size: 11px; font-weight: 600; }

.lui-chart-crosshair { stroke: var(--border-strong); stroke-width: 1; stroke-dasharray: 3 3; }
.lui-chart-dot { stroke: var(--surface); stroke-width: 2; }
.lui-chart-line { fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.lui-chart-area { stroke: none; opacity: .16; }
.lui-chart-bar { rx: 3; transition: opacity var(--dur-fast); }
.lui-chart-bar[data-dim] { opacity: .45; }

.lui-chart-empty {
  display: grid; place-items: center; min-height: 120px;
  color: var(--text-3); font-size: var(--fs-sm);
}

/* tooltip */
.lui-chart-tip {
  position: absolute; z-index: 2; pointer-events: none;
  min-width: 118px; max-width: 220px; padding: 8px 10px;
  border: 1px solid var(--border); border-radius: var(--r-sm);
  background: var(--surface); box-shadow: var(--sh-lg);
  font-size: 12px; color: var(--text);
}
.lui-chart-tip-title {
  margin-bottom: 5px; padding-bottom: 5px; border-bottom: 1px solid var(--border);
  font-weight: 650; color: var(--text-2);
}
.lui-chart-tip-row { display: flex; align-items: center; gap: 7px; line-height: 1.7; }
.lui-chart-tip-swatch { flex: none; width: 8px; height: 8px; border-radius: 2px; }
.lui-chart-tip-label { flex: 1; min-width: 0; color: var(--text-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lui-chart-tip-value { font-weight: 650; font-variant-numeric: tabular-nums; }

@media (prefers-reduced-motion: reduce) {
  .lui-barchart-bar { animation: none; }
}

/* ---------- ScatterChart ---------- */
.lui-chart-point { opacity: .78; transition: opacity var(--dur-fast); cursor: default; }
.lui-chart-point:hover, .lui-chart-point[data-active] { opacity: 1; stroke: var(--surface); stroke-width: 2; }

"use client";
import * as React from "react";
import { cn } from "./cn";

/**
 * Gedeelde bouwstenen voor de grafieken: kleuren, schalen, assen, paden en
 * de tooltip. Elke grafiek tekent zelf zijn vorm, maar rekent met dit bestand,
 * zodat assen en tooltips er overal hetzelfde uitzien.
 */

export const CHART_PALETTE = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
  "var(--chart-6)",
];

/** Kleur nummer `index` uit het palet, tenzij de reeks er zelf een meegeeft. */
export function chartColor(index: number, eigen?: string) {
  return eigen ?? CHART_PALETTE[index % CHART_PALETTE.length];
}

/** Eén reeks getallen met een naam; de x-as komt uit `labels` van de grafiek. */
export interface ChartSeries {
  name: string;
  data: number[];
  color?: string;
}

export interface ChartMargin {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export interface ChartPoint {
  x: number;
  y: number;
}

/* ------------------------------- afmeting ------------------------------- */

/**
 * Meet de breedte van de container, zodat de SVG op ware grootte tekent en
 * tekst en lijnen niet uitgerekt worden. Tijdens SSR geldt `standaard`.
 */
export function useChartWidth(
  ref: React.RefObject<HTMLElement | null>,
  standaard = 560
): number {
  const [breedte, setBreedte] = React.useState(standaard);

  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const meet = () => setBreedte(Math.max(el.clientWidth, 120));
    meet();
    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", meet);
      return () => window.removeEventListener("resize", meet);
    }
    const waarnemer = new ResizeObserver(meet);
    waarnemer.observe(el);
    return () => waarnemer.disconnect();
  }, [ref]);

  return breedte;
}

/* -------------------------------- schaal -------------------------------- */

export interface ChartScale {
  min: number;
  max: number;
  ticks: number[];
}

/**
 * Ronde asgrenzen met leesbare stappen (1, 2, 2.5, 5, 10 …) rond de data.
 */
export function niceScale(min: number, max: number, aantal = 5): ChartScale {
  if (!Number.isFinite(min) || !Number.isFinite(max)) return { min: 0, max: 1, ticks: [0, 1] };
  if (min === max) {
    const marge = Math.abs(min) || 1;
    min -= marge;
    max += marge;
  }
  const ruwe = (max - min) / Math.max(aantal, 1);
  const grootte = Math.pow(10, Math.floor(Math.log10(ruwe)));
  const genormaliseerd = ruwe / grootte;
  const factor = genormaliseerd <= 1 ? 1 : genormaliseerd <= 2 ? 2 : genormaliseerd <= 2.5 ? 2.5 : genormaliseerd <= 5 ? 5 : 10;
  const stap = factor * grootte;
  const onder = Math.floor(min / stap) * stap;
  const boven = Math.ceil(max / stap) * stap;

  const ticks: number[] = [];
  /* In stappen tellen stapelt afrondingsfouten op; daarom via een teller. */
  const stappen = Math.round((boven - onder) / stap);
  for (let i = 0; i <= stappen; i += 1) ticks.push(Number((onder + i * stap).toPrecision(12)));

  return { min: onder, max: boven, ticks };
}

/* ------------------------------- opmaak --------------------------------- */

/** Korte notatie: 1,2 k · 3,4 mln · 2,1 mld. */
export function formatCompact(waarde: number, locale = "nl-BE"): string {
  const absoluut = Math.abs(waarde);
  const eenheden: Array<[number, string]> = [
    [1e9, " mld"],
    [1e6, " mln"],
    [1e3, " k"],
  ];
  for (const [drempel, achtervoegsel] of eenheden) {
    if (absoluut >= drempel) {
      const getal = waarde / drempel;
      return (
        getal.toLocaleString(locale, { maximumFractionDigits: Math.abs(getal) < 10 ? 1 : 0 }) +
        achtervoegsel
      );
    }
  }
  return waarde.toLocaleString(locale, { maximumFractionDigits: 2 });
}

/** Standaardopmaak voor asticks en tooltips. */
export function formatChartValue(
  waarde: number,
  opties?: Intl.NumberFormatOptions,
  locale = "nl-BE"
): string {
  if (opties) return waarde.toLocaleString(locale, opties);
  return waarde.toLocaleString(locale, { maximumFractionDigits: 2 });
}

/* --------------------------------- paden -------------------------------- */

const rond = (n: number) => Math.round(n * 100) / 100;

/**
 * Lijn door de punten. Met `curved` een Catmull-Rom-spline die tussen de
 * punten door loopt zonder eroverheen te schieten.
 */
export function linePath(punten: ChartPoint[], curved = false): string {
  if (punten.length === 0) return "";
  if (punten.length === 1) return `M ${rond(punten[0].x)} ${rond(punten[0].y)}`;
  if (!curved) {
    return punten.map((punt, i) => `${i === 0 ? "M" : "L"} ${rond(punt.x)} ${rond(punt.y)}`).join(" ");
  }

  let d = `M ${rond(punten[0].x)} ${rond(punten[0].y)}`;
  for (let i = 0; i < punten.length - 1; i += 1) {
    const p0 = punten[i - 1] ?? punten[i];
    const p1 = punten[i];
    const p2 = punten[i + 1];
    const p3 = punten[i + 2] ?? p2;
    const c1 = { x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6 };
    const c2 = { x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6 };
    d += ` C ${rond(c1.x)} ${rond(c1.y)}, ${rond(c2.x)} ${rond(c2.y)}, ${rond(p2.x)} ${rond(p2.y)}`;
  }
  return d;
}

/** Hetzelfde pad, maar gesloten tot aan de nullijn, om het vlak te vullen. */
export function areaPath(punten: ChartPoint[], nullijn: number, curved = false): string {
  if (punten.length === 0) return "";
  const lijn = linePath(punten, curved);
  const eerste = punten[0];
  const laatste = punten[punten.length - 1];
  return `${lijn} L ${rond(laatste.x)} ${rond(nullijn)} L ${rond(eerste.x)} ${rond(nullijn)} Z`;
}

/* ------------------------------- onderdelen ------------------------------ */

export interface ChartGridProps {
  ticks: number[];
  /** Zet een tickwaarde om naar een y-coördinaat. */
  toY: (waarde: number) => number;
  x1: number;
  x2: number;
}

/** Horizontale hulplijnen op de tickhoogtes. */
export function ChartGrid({ ticks, toY, x1, x2 }: ChartGridProps) {
  return (
    <g aria-hidden="true">
      {ticks.map((tick) => (
        <line key={tick} x1={x1} x2={x2} y1={toY(tick)} y2={toY(tick)} className="lui-chart-grid" />
      ))}
    </g>
  );
}

export interface ChartAxisYProps {
  ticks: number[];
  toY: (waarde: number) => number;
  x: number;
  format?: (waarde: number) => string;
  /** Labels rechts van de as in plaats van links. */
  right?: boolean;
}

/** Tekstlabels bij de verticale as. */
export function ChartAxisY({ ticks, toY, x, format = formatCompact, right }: ChartAxisYProps) {
  return (
    <g aria-hidden="true">
      {ticks.map((tick) => (
        <text
          key={tick}
          x={x}
          y={toY(tick)}
          dy="0.32em"
          textAnchor={right ? "start" : "end"}
          className="lui-chart-tick"
        >
          {format(tick)}
        </text>
      ))}
    </g>
  );
}

export interface ChartAxisXProps {
  labels: string[];
  /** Zet een index om naar een x-coördinaat. */
  toX: (index: number) => number;
  y: number;
  /** Laat labels weg zodra ze niet meer passen. */
  maxLabels?: number;
}

/** Tekstlabels onder de horizontale as; dunt uit als er te weinig plaats is. */
export function ChartAxisX({ labels, toX, y, maxLabels = 8 }: ChartAxisXProps) {
  const stap = Math.max(1, Math.ceil(labels.length / Math.max(maxLabels, 1)));
  return (
    <g aria-hidden="true">
      {labels.map((label, index) =>
        index % stap === 0 || index === labels.length - 1 ? (
          <text key={`${label}-${index}`} x={toX(index)} y={y} textAnchor="middle" className="lui-chart-tick">
            {label}
          </text>
        ) : null
      )}
    </g>
  );
}

export interface ChartTooltipItem {
  label: React.ReactNode;
  value: React.ReactNode;
  color?: string;
}

export interface ChartTooltipProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Positie binnen de grafiekcontainer, in pixels. */
  x: number;
  y: number;
  title?: React.ReactNode;
  items: ChartTooltipItem[];
  /** Breedte van de container, om binnen de rand te blijven. */
  containerWidth?: number;
}

/**
 * Zwevend kaartje bij het punt onder de muis. Hoort in een container met
 * `position: relative` (de klasse lui-chart doet dat).
 */
export const ChartTooltip = React.forwardRef<HTMLDivElement, ChartTooltipProps>(function ChartTooltip(
  { x, y, title, items, containerWidth, className, style, ...rest },
  ref
) {
  /* Bij de rechterrand klapt het kaartje naar links, anders valt het weg. */
  const naarLinks = containerWidth !== undefined && x > containerWidth - 130;

  return (
    <div
      ref={ref}
      role="tooltip"
      className={cn("lui-chart-tip", className)}
      style={{
        insetInlineStart: x,
        top: y,
        transform: `translate(${naarLinks ? "calc(-100% - 12px)" : "12px"}, -50%)`,
        ...style,
      }}
      {...rest}
    >
      {title !== undefined && <div className="lui-chart-tip-title">{title}</div>}
      {items.map((item, index) => (
        <div className="lui-chart-tip-row" key={index}>
          {item.color && <span className="lui-chart-tip-swatch" style={{ background: item.color }} />}
          <span className="lui-chart-tip-label">{item.label}</span>
          <span className="lui-chart-tip-value">{item.value}</span>
        </div>
      ))}
    </div>
  );
});

/* -------------------------------- hover --------------------------------- */

/**
 * Volgt welke kolom onder de muis staat in een grafiek met vaste stappen.
 * Geeft handlers voor het hele SVG-vlak terug; de grafiek tekent zelf de
 * crosshair en de tooltip.
 */
export function useChartHover(aantal: number, links: number, stap: number) {
  const [index, setIndex] = React.useState<number | null>(null);

  const onPointerMove = React.useCallback(
    (event: React.PointerEvent<SVGSVGElement>) => {
      const rect = event.currentTarget.getBoundingClientRect();
      const x = event.clientX - rect.left - links;
      const dichtst = Math.round(x / (stap || 1));
      setIndex(Math.min(Math.max(dichtst, 0), Math.max(aantal - 1, 0)));
    },
    [aantal, links, stap]
  );

  const onPointerLeave = React.useCallback(() => setIndex(null), []);

  return { index, onPointerMove, onPointerLeave, reset: onPointerLeave };
}
